const buffer = $input.first().json.buffer_items || [];

function safeText(nodeName) {
  try {
    const node = $(nodeName).first();
    return node?.json?.unified_text || null;
  } catch (e) {
    return null;
  }
}

const myMessage = (
  safeText('Set · Audio → Text') ||
  safeText('Set · Image Marker') ||
  safeText('Set · Plain Text') ||
  ''
).trim();

const lastInBuffer = (buffer.length > 0 ? buffer[buffer.length - 1] : '').trim();
const isLast = lastInBuffer === myMessage;

return [{
  json: {
    is_last: isLast,
    buffer_size: buffer.length,
    concatenated: buffer.join('\n').trim(),
    my_message: myMessage,
  }
}];

