parameters.jsCode:
const itemsIn = $input.all();
const messages = [];
for (const item of itemsIn) {
  const out = item.json.output;
  if (out && typeof out === 'object' && Array.isArray(out.mensajes)) {
    out.mensajes.forEach(m => { if (m && String(m).trim()) messages.push(String(m).trim()); });
    continue;
  }
  const text = (typeof out === 'string' ? out : (item.json?.text || item.json?.response || '')).trim();
  if (text) text.split(/\n\s*\n/).map(s => s.trim()).filter(Boolean).forEach(m => messages.push(m));
}
return messages.map((m, i) => ({ json: { content: m, index: i, total: messages.length } }));

function safeGet(obj, path, def = null) {
  if (!obj) return def;
  return path.split('.').reduce(
    (o, k) => (o && o[k] !== undefined && o[k] !== null) ? o[k] : def,
    obj
  );
}

const out = [];
for (const item of items) {
  let body = item.json.body || item.json;
  if (typeof body === 'string') {
    try { body = JSON.parse(body); } catch (e) {}
  }

  const sender   = body.sender || {};
  const conv     = body.conversation || {};
  const msgInner = safeGet(conv, 'messages.0') || {};

  const chType = (conv.channel || '').toLowerCase();
  let channel = 'unknown';
  if (chType.includes('whatsapp'))                             channel = 'whatsapp';
  else if (chType.includes('instagram'))                       channel = 'instagram';
  else if (chType.includes('facebook'))                        channel = 'facebook';
  else if (chType.includes('api') || chType.includes('widget') || chType.includes('webchat')) channel = 'webchat';

  const isIncoming = (body.message_type === 'incoming');
  const senderType = (msgInner.sender_type || '').toLowerCase();

  // ── Identidad del contacto ───────────────────────────────────────────────
  // OJO: en un mensaje SALIENTE, `sender` es el asesor, no el cliente. El
  // contacto siempre está en conversation.meta.sender, así que de ahí se lee.
  const contactoId  = String(safeGet(conv, 'meta.sender.id') || sender.id || '');
  const telContacto = safeGet(conv, 'meta.sender.phone_number') || sender.phone_number || null;

  // Usuario de Instagram. Se busca en meta.sender primero por la misma razón:
  // en un saliente, `sender` es el asesor y no trae el handle del cliente.
  const igRaw = String(
    safeGet(conv, 'meta.sender.additional_attributes.social_profiles.instagram') ||
    safeGet(conv, 'meta.sender.identifier') ||
    safeGet(sender, 'additional_attributes.social_profiles.instagram') ||
    sender.identifier || ''
  ).trim().toLowerCase();
  const igHandle = igRaw ? (igRaw.startsWith('@') ? igRaw : '@' + igRaw) : '';

  // Identidad por canal:
  //   WhatsApp  -> el número, en E.164          (+5219996167830)
  //   Instagram -> el usuario                    (@eiwriwewer)
  //   Messenger -> FB- + id de contacto Chatwoot (FB-161), porque Messenger
  //                no expone un usuario público utilizable.
  let userId;
  if (channel === 'facebook')       userId = contactoId ? 'FB-' + contactoId : '';
  else if (channel === 'instagram') userId = igHandle || (contactoId ? 'IG-' + contactoId : '');
  else if (telContacto) {
    // WhatsApp: SIEMPRE el número, en formato E.164 (+52…). Se normaliza a
    // "+" + dígitos para que un mismo cliente no genere dos leads si algún
    // día Chatwoot manda el número sin "+" o con espacios.
    const dig = String(telContacto).replace(/\D/g, '');
    userId = dig ? '+' + dig : String(telContacto);
  }
  else userId =
    sender.identifier ||
    safeGet(sender, 'additional_attributes.social_profiles.instagram') ||
    contactoId;

  // ── Nombre de perfil: solo es confiable en WhatsApp ──────────────────────
  // En Messenger e Instagram, Chatwoot SIEMPRE rellena sender.name con el
  // nombre público de la cuenta, que suele ser un alias ("John Doe",
  // "El Chino Motos", "Mari 🌸"). Si lo dejamos pasar, el Hydrator lo guarda
  // como `nombre` del lead, el contexto llega con "Nombre guardado en CRM"
  // lleno, y el agente NUNCA le pregunta cómo se llama de verdad.
  const esRedSocial  = (channel === 'facebook' || channel === 'instagram');
  const nombrePerfil = String(safeGet(conv, 'meta.sender.name') || sender.name || '').trim();
  const senderName   = esRedSocial ? '' : (nombrePerfil || 'Cliente');

  // ── Auto-pausa: ¿este mensaje saliente lo escribió un ASESOR humano? ─────
  // Los mensajes del propio bot también llegan como 'outgoing', así que se
  // distinguen por el id del usuario dueño del token de Chatwoot.
  // FAIL-SAFE: si CHATWOOT_BOT_USER_ID no está configurado, nunca pausa.
  const BOT_ID = String((typeof $vars !== 'undefined' && $vars && $vars.CHATWOOT_BOT_USER_ID) || '').trim();
  const senderId = String(sender.id || '');
  const escribioHumano = (!isIncoming && !body.private && !!BOT_ID && senderId !== BOT_ID && !!senderId);

  // Llave del cliente para pausar/invalidar cache. Debe coincidir SIEMPRE con
  // user_id_canal, también en los mensajes salientes.
  // La llave para pausar/invalidar cache es SIEMPRE la misma que user_id_canal,
  // también en los mensajes salientes.
  const clienteTel = userId;

  const attachments = body.attachments || msgInner.attachments || [];
  const firstAtt    = attachments[0] || null;
  const mtype       = firstAtt ? (firstAtt.file_type || 'file') : 'text';

  out.push({
    json: {
      is_incoming:     isIncoming,
      sender_type:     senderType,
      account_id:      safeGet(body, 'account.id'),
      conversation_id: conv.id || body.conversation_id,
      contact_id:      sender.id,
      user_id_canal:   userId,
      sender_name:     senderName,
      message_id:      String(body.id || ''),
      wamid:           body.source_id || safeGet(msgInner, 'source_id') || null,
      message_text:    body.content || body.processed_message_content || '',
      message_type:    mtype,
      attachment_url:  firstAtt ? (firstAtt.data_url || firstAtt.url) : null,
      channel,
      inbox_id:        safeGet(body, 'inbox.id'),
      inbox_name:      safeGet(body, 'inbox.name'),
      event:           body.event || 'message_created',
      created_at:      body.created_at,
      received_at:     new Date().toISOString(),
      escribio_humano: escribioHumano,
      agent_sender_id: isIncoming ? null : senderId,
      cliente_id_canal: clienteTel,
      // Se conserva el nombre de perfil por si el asesor lo necesita, pero
      // NO viaja como sender_name: el agente no debe usarlo como nombre real.
      nombre_perfil:    nombrePerfil,
      nombre_confiable: !esRedSocial
    }
  });
}
return out;

// ═══════════════════════════════════════════════════════════════════════
// Code · Time Context
// Genera hora/día y estado del asesor humano en zona America/Merida (UTC-6).
// Debe correr DESPUÉS del Lead Hydrator y ANTES del Agent · Comercial.
//
// Horarios manejados:
// - SUCURSAL FÍSICA (para agendar citas): Lun-Vie 9:00-18:30, Sáb 9:00-14:30, Dom cerrado
// - ASESOR HUMANO (para handoff):        Lun-Vie 8:00-20:00, Sáb 8:00-16:00, Dom cerrado
// ═══════════════════════════════════════════════════════════════════════

// Toma el input previo (Lead Hydrator normalmente)
const lead = $input.first().json;

// Zona horaria fija: Yucatán (UTC-6, sin DST). Aplica a todas las sucursales por default.
const zona = 'America/Merida';

// ── Calcular hora actual en la zona ──
const now = new Date();
const parts = new Intl.DateTimeFormat('en-US', {
  timeZone: zona,
  hour12: false,
  weekday: 'long',
  hour: '2-digit',
  minute: '2-digit',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
}).formatToParts(now);

const partObj = {};
for (const p of parts) partObj[p.type] = p.value;

const hora = parseInt(partObj.hour, 10);       // 0-23
const minuto = parseInt(partObj.minute, 10);
const weekdayEN = partObj.weekday;             // Monday, Tuesday, ...

// Mapear día en inglés a español y número (0=domingo ... 6=sábado)
const DIAS_EN_A_ES = {
  'Sunday': 'domingo', 'Monday': 'lunes', 'Tuesday': 'martes',
  'Wednesday': 'miércoles', 'Thursday': 'jueves', 'Friday': 'viernes',
  'Saturday': 'sábado'
};
const DIAS_EN_A_NUM = {
  'Sunday': 0, 'Monday': 1, 'Tuesday': 2, 'Wednesday': 3,
  'Thursday': 4, 'Friday': 5, 'Saturday': 6
};
const diaNombre = DIAS_EN_A_ES[weekdayEN] || 'desconocido';
const diaNum = DIAS_EN_A_NUM[weekdayEN] ?? -1;

// ── Ventana ASESOR HUMANO (para handoff): Lun-Vie 8-20h, Sáb 8-16h, Dom cerrado ──
let asesorDisponible = false;
let estadoAsesor = '';

if (diaNum === 0) {
  asesorDisponible = false;
  estadoAsesor = 'domingo_cerrado';
} else if (diaNum >= 1 && diaNum <= 5) {
  if (hora < 8) {
    asesorDisponible = false;
    estadoAsesor = 'muy_temprano';
  } else if (hora >= 20) {
    asesorDisponible = false;
    estadoAsesor = 'ya_cerrado';
  } else {
    asesorDisponible = true;
    estadoAsesor = 'dentro_horario';
  }
} else if (diaNum === 6) {
  if (hora < 8) {
    asesorDisponible = false;
    estadoAsesor = 'muy_temprano';
  } else if (hora >= 16) {
    asesorDisponible = false;
    estadoAsesor = 'sabado_cerrado_tarde';
  } else {
    asesorDisponible = true;
    estadoAsesor = 'dentro_horario';
  }
}

// ── Ventana SUCURSAL FÍSICA: Lun-Vie 9-18:30, Sáb 9-14:30, Dom cerrado ──
const horaDecimal = hora + (minuto / 60);
let sucursalAbierta = false;
if (diaNum >= 1 && diaNum <= 5) {
  sucursalAbierta = horaDecimal >= 9 && horaDecimal < 18.5;
} else if (diaNum === 6) {
  sucursalAbierta = horaDecimal >= 9 && horaDecimal < 14.5;
}

// ── Próxima ventana de atención del asesor humano ──
let proximaAtencionAsesor = '';
if (asesorDisponible) {
  proximaAtencionAsesor = '';
} else if (diaNum === 6 && hora >= 16) {
  proximaAtencionAsesor = 'el lunes a partir de las 8:00 am';
} else if (diaNum === 0) {
  proximaAtencionAsesor = 'el lunes a partir de las 8:00 am';
} else if (diaNum >= 1 && diaNum <= 5 && hora >= 20) {
  if (diaNum === 5) {
    proximaAtencionAsesor = 'mañana sábado a partir de las 8:00 am';
  } else {
    proximaAtencionAsesor = 'mañana a partir de las 8:00 am';
  }
} else if (diaNum >= 1 && diaNum <= 5 && hora < 8) {
  proximaAtencionAsesor = 'hoy a partir de las 8:00 am';
} else if (diaNum === 6 && hora < 8) {
  proximaAtencionAsesor = 'hoy a partir de las 8:00 am';
}

// ── Resultado: preserva todo el contexto anterior + agrega los campos nuevos ──
return [{
  json: {
    ...lead,
    hora_actual: `${String(hora).padStart(2, '0')}:${String(minuto).padStart(2, '0')}`,
    dia_actual: diaNombre,
    dia_num: diaNum,
    zona_horaria: zona,
    asesor_disponible_ahora: asesorDisponible,
    estado_asesor: estadoAsesor,
    proxima_atencion_asesor: proximaAtencionAsesor,
    sucursal_fisica_abierta_ahora: sucursalAbierta,
    es_fin_de_semana: diaNum === 0 || diaNum === 6
  }
}];

const buffer = $input.first().json.buffer_items || [];

function safeText(nodeName) {
  try {
    const node = $(nodeName).first();
    return node?.json?.unified_text || null;
  } catch (e) {
    return null;
  }
}

const myMessage = (
  safeText('Set · Audio → Text1') ||
  safeText('Set · Image Marker1') ||
  safeText('Set · Plain Text1') ||
  ''
).trim();

const lastInBuffer = (buffer.length > 0 ? buffer[buffer.length - 1] : '').trim();
const isLast = lastInBuffer === myMessage;

return [{
  json: {
    is_last: isLast,
    buffer_size: buffer.length,
    concatenated: buffer.join('\n').trim(),
    my_message: myMessage,
  }
}];

